// Dijital saat: DS1307 zamanı tutar, 16x2 LCD tarih ve saati gösterir.
#include <LiquidCrystal.h>
#include <RTClib.h>

const int LCD_RS = 12;
const int LCD_E = 11;
const int LCD_D4 = 5;
const int LCD_D5 = 4;
const int LCD_D6 = 3;
const int LCD_D7 = 2;

LiquidCrystal lcd(LCD_RS, LCD_E, LCD_D4, LCD_D5, LCD_D6, LCD_D7);
RTC_DS1307 rtc;

// LCD Türkçe harf gösteremez; gün adları ASCII.
const char GUNLER[7][4] = {"Paz", "Pzt", "Sal", "Car", "Per", "Cum", "Cmt"};
int sonSaniye = -1;

// Tek haneli sayının önüne 0 koyar (ör. 7 -> 07).
void ikiHane(int sayi) {
  if (sayi < 10) lcd.print('0');
  lcd.print(sayi);
}

void setup() {
  Serial.begin(9600);
  lcd.begin(16, 2);

  if (!rtc.begin()) {
    lcd.print("RTC bulunamadi");
    Serial.println("DS1307 bulunamadi. SDA=A4, SCL=A5 kablolarini kontrol et.");
    while (true) delay(1000);
  }
  if (!rtc.isrunning()) {
    // Saat durmuşsa (ilk açılış, pil bitmiş) derleme zamanına ayarla.
    rtc.adjust(DateTime(F(__DATE__), F(__TIME__)));
    Serial.println("Saat derleme zamanina ayarlandi.");
  }
}

void loop() {
  DateTime simdi = rtc.now();
  if (simdi.second() == sonSaniye) {
    delay(50);
    return;
  }
  sonSaniye = simdi.second();

  // Üst satır: 24.11.2026  Sal
  lcd.setCursor(0, 0);
  ikiHane(simdi.day());
  lcd.print('.');
  ikiHane(simdi.month());
  lcd.print('.');
  lcd.print(simdi.year());
  lcd.print("  ");
  lcd.print(GUNLER[simdi.dayOfTheWeek()]);

  // Alt satır: ortada 14:05:09
  lcd.setCursor(4, 1);
  ikiHane(simdi.hour());
  lcd.print(':');
  ikiHane(simdi.minute());
  lcd.print(':');
  ikiHane(simdi.second());

  char yazi[20];
  sprintf(yazi, "%02d.%02d.%04d %02d:%02d:%02d", simdi.day(), simdi.month(), simdi.year(),
          simdi.hour(), simdi.minute(), simdi.second());
  Serial.println(yazi);
}
